begin;
\ir fixtures/clinical.sql
reset role;
insert into public.locations(id,practice_id,name,timezone)values(pg_temp.id(710),pg_temp.practice(),'Synthetic waitlist second clinic','Etc/UTC');
create function pg_temp.wait_day()returns date language sql as $$select(clock_timestamp()at time zone'Etc/UTC')::date+7$$;
create function pg_temp.wait_input(permission boolean default true)returns jsonb language sql as $$select jsonb_build_object('patient_id',pg_temp.patient(),'type_id',pg_temp.id(700),'type_version',1,'date_from',pg_temp.wait_day(),'date_to',pg_temp.wait_day()+1,'minute_start',540,'minute_end',1020,'contact_permission',permission,'permission_source',case when permission then'Synthetic request permission'else''end)$$;
create function pg_temp.wait_command(action text,k integer,n integer default 720,expected integer default 1,input jsonb default '{}')returns jsonb language sql as $$select public.doctor_waitlist_command(pg_temp.practice(),pg_temp.location(),pg_temp.id(n),expected,action,input,pg_temp.id(k))$$;
create function pg_temp.offer_input(minute integer default 600,expiry timestamptz default clock_timestamp()+interval'1 hour')returns jsonb language sql as $$select jsonb_build_object('date',pg_temp.wait_day(),'minute',minute,'schedule_version',1,'location_version',1,'expires_at',expiry)$$;
set local role authenticated;select pg_temp.claim(1);
select public.doctor_write_schedule(pg_temp.practice(),pg_temp.location(),0,jsonb_build_object('slot_minutes',10,'weekly',(select jsonb_agg(jsonb_build_object('weekday',d,'start',540,'end',1080))from generate_series(0,6)d),'exceptions','[]'::jsonb),pg_temp.id(701),1);
select public.doctor_write_schedule(pg_temp.practice(),pg_temp.id(710),0,jsonb_build_object('slot_minutes',10,'weekly',(select jsonb_agg(jsonb_build_object('weekday',d,'start',540,'end',1080))from generate_series(0,6)d),'exceptions','[]'::jsonb),pg_temp.id(702),1);
select public.doctor_write_consultation_type(pg_temp.practice(),pg_temp.location(),pg_temp.id(700),0,jsonb_build_object('name','Synthetic waitlist type','duration_minutes',30,'buffer_before',10,'buffer_after',5,'capacity',1,'location_ids',jsonb_build_array(pg_temp.location(),pg_temp.id(710)),'active',true),pg_temp.id(703));
select is(pg_temp.wait_command('create',721,720,0,pg_temp.wait_input())->>'state','waiting','DOS-M3-002-C01: explicit scoped request begins waiting');
select is(pg_temp.wait_command('create',721,720,0,pg_temp.wait_input())->>'version','1','creation retry is exact');
select throws_ok($$select pg_temp.wait_command('create',721,720,0,pg_temp.wait_input(false))$$,'22023','DOCTOR_IDEMPOTENCY_CONFLICT','changed retry intent rejected');
select is(pg_temp.wait_command('create',731,730,0,pg_temp.wait_input(false))->>'state','waiting','permission defaults off and permits a noncontactable request');
select throws_ok($$select pg_temp.wait_command('offer',732,730,1,pg_temp.offer_input())$$,'42501','DOCTOR_WAITLIST_PERMISSION_REQUIRED','no offer without explicit request permission');
select is(pg_temp.wait_command('offer',722,720,1,pg_temp.offer_input())->>'state','offered','offer reserves exact slot and expiry without sending');
select is((public.doctor_location_archive_status(pg_temp.practice(),pg_temp.location())->>'can_archive')::boolean,false,'active reservation prevents an inaccessible archived-clinic hold');
select is(public.doctor_waitlist(pg_temp.practice(),pg_temp.location())->>'external_messages','disabled','no provider delivery claim');
select is((select value->>'reason'from jsonb_array_elements(public.doctor_consultation_availability(pg_temp.practice(),pg_temp.id(710),pg_temp.wait_day(),pg_temp.id(700),1)->'slots')where(value->>'minute')::integer=600),'busy','offer reserves doctor capacity across clinics');
select throws_ok($$select public.doctor_book_appointment(pg_temp.practice(),pg_temp.id(710),pg_temp.patient(),pg_temp.wait_day(),620,1,1,pg_temp.id(735))$$,'40001','DOCTOR_APPOINTMENT_CONFLICT','legacy booking cannot consume buffered reserved capacity');
select pg_temp.wait_command('create',741,740,0,pg_temp.wait_input());
select throws_ok($$select pg_temp.wait_command('offer',742,740,1,pg_temp.offer_input())$$,'40001','DOCTOR_APPOINTMENT_CONFLICT','another request cannot reserve the same commitment');
select throws_ok($$select pg_temp.wait_command('accept',744,720,1,'{"reason":"Synthetic accepted request"}')$$,'40001','DOCTOR_WAITLIST_CONFLICT','acceptance requires current entry version');
select pg_temp.put('wait_accepted',pg_temp.wait_command('accept',723,720,2,'{"reason":"Synthetic explicit acceptance recorded"}'));
select is(pg_temp.v('wait_accepted')->>'state','accepted','DOS-M3-002-C02: acceptance atomically books reserved slot');
select is(pg_temp.wait_command('accept',723,720,2,'{"reason":"Synthetic explicit acceptance recorded"}'),pg_temp.v('wait_accepted'),'acceptance retry does not make a second appointment');
select is(public.doctor_waitlist_history(pg_temp.practice(),pg_temp.location(),pg_temp.id(720))->>'total','3','request, offer and acceptance history retained');
select throws_ok($$select pg_temp.wait_command('accept',724,720,2,'{"reason":"Second acceptance"}')$$,'40001','DOCTOR_WAITLIST_CONFLICT','another acceptance intent cannot repeat completion');
select pg_temp.wait_command('revoke_contact',725,720,3,'{"reason":"Synthetic permission withdrawn"}');
select throws_ok($$select pg_temp.wait_command('accept',723,720,2,'{"reason":"Synthetic explicit acceptance recorded"}')$$,'42501','DOCTOR_WAITLIST_PERMISSION_REQUIRED','revoked permission cannot replay a cached acceptance');
select pg_temp.wait_command('create',751,750,0,pg_temp.wait_input());
select pg_temp.wait_command('offer',752,750,1,pg_temp.offer_input(800));
select is(pg_temp.wait_command('cancel',753,750,2,'{"reason":"Synthetic request cancelled"}')->>'state','cancelled','cancellation preserves request history');
select lives_ok($$select public.doctor_book_consultation(pg_temp.practice(),pg_temp.id(710),pg_temp.patient(),pg_temp.wait_day(),800,1,1,pg_temp.id(754),pg_temp.id(700),1)$$,'cancelled offer returns capacity');
select pg_temp.wait_command('create',761,760,0,pg_temp.wait_input());
select pg_temp.wait_command('offer',762,760,1,pg_temp.offer_input(900,clock_timestamp()+interval'500 milliseconds'));
select pg_sleep(0.6);
select is((select value->>'state'from jsonb_array_elements(public.doctor_waitlist(pg_temp.practice(),pg_temp.location())->'rows')where value->>'id'=pg_temp.id(760)::text),'expired','DOS-M3-002-C03: query projects effective expiry from database clock');
select throws_ok($$select pg_temp.wait_command('accept',763,760,2,'{"reason":"Late acceptance"}')$$,'40001','DOCTOR_WAITLIST_EXPIRED_OR_CONFLICT','expired offers cannot book');
select lives_ok($$select public.doctor_book_consultation(pg_temp.practice(),pg_temp.id(710),pg_temp.patient(),pg_temp.wait_day(),900,1,1,pg_temp.id(764),pg_temp.id(700),1)$$,'expired reservation stops consuming capacity before cleanup');
select is(pg_temp.wait_command('expire',765,760,2)->>'state','expired','explicit cleanup records terminal expiry');
select is(public.doctor_waitlist_history(pg_temp.practice(),pg_temp.location(),pg_temp.id(760))->>'total','3','expiry retains issued offer and its history');
select pg_temp.wait_command('create',771,770,0,pg_temp.wait_input());select pg_temp.wait_command('offer',772,770,1,pg_temp.offer_input(700));
select is(pg_temp.wait_command('revoke_contact',773,770,2,'{"reason":"Synthetic consent withdrawn"}')->>'state','cancelled','permission withdrawal cancels an outstanding offer');
select lives_ok($$select public.doctor_book_consultation(pg_temp.practice(),pg_temp.id(710),pg_temp.patient(),pg_temp.wait_day(),700,1,1,pg_temp.id(774),pg_temp.id(700),1)$$,'withdrawn permission returns held capacity');
select pg_temp.claim(3);
select throws_ok($$select public.doctor_waitlist(pg_temp.practice(),pg_temp.location())$$,'42501','DOCTOR_ACCESS_DENIED','patients-only secretary cannot read scheduling requests');
select pg_temp.claim(2);
select throws_ok($$select public.doctor_waitlist(pg_temp.practice(),pg_temp.location())$$,'42501','DOCTOR_ACCESS_DENIED','independent owner cannot read waitlist');
reset role;
select is((select count(*)::integer from public.appointments where id=(pg_temp.v('wait_accepted')->>'appointment_id')::uuid),1,'one accepted request produces exactly one appointment');
select is((select count(*)::integer from public.waitlist_offers where entry_id=pg_temp.id(750)and state='cancelled'),1,'cancelled offer remains stored');
select throws_ok($$update public.waitlist_offers set expires_at=clock_timestamp()+interval'2 hours'where entry_id=pg_temp.id(720)$$,'22023','DOCTOR_WAITLIST_OFFER_IMMUTABLE','issued hold fields cannot be rewritten while preserving a fake history');
select ok(not has_table_privilege('authenticated','public.waitlist_entries','INSERT'),'direct client request writes denied');
select ok(not has_table_privilege('authenticated','public.waitlist_offers','UPDATE'),'direct reservation mutation denied');
select ok(not has_function_privilege('anon','public.doctor_waitlist(uuid,uuid,integer,text,text)','EXECUTE'),'anonymous request discovery denied');
select * from finish();rollback;
